solution.solution.cpp:
#include <string>
#include <type_traits>

template <typename T>
std::string inspect(const T& value)
{
    if constexpr (std::is_same_v<T, bool>)
    {
        return value ? "bool true" : "bool false";
    }
    else if constexpr (std::is_integral_v<T>)
    {
        return "integer " + std::to_string(value);
    }
    else if constexpr (std::is_floating_point_v<T>)
    {
        return "decimal " + std::to_string(value);
    }
    else if constexpr (std::is_pointer_v<T>)
    {
        return value == nullptr ? std::string{ "null pointer" } : "pointer to " + inspect(*value);
    }
    else if constexpr (requires { value.size(); })
    {
        return "container of " + std::to_string(value.size());
    }
    else
    {
        return "unknown";
    }
}

unitTests:
struct Mystery {};
TEST("numbers and bool") { CHECK_EQ(inspect(42), "integer 42"); CHECK_EQ(inspect(-7L), "integer -7"); CHECK_EQ(inspect(2.5), "decimal 2.500000"); CHECK_EQ(inspect(true), "bool true"); CHECK_EQ(inspect(false), "bool false"); }
TEST("pointers are followed") { int n{ 9 }; int* p{ &n }; int** pp{ &p }; int* none{ nullptr }; CHECK_EQ(inspect(p), "pointer to integer 9"); CHECK_EQ(inspect(pp), "pointer to pointer to integer 9"); CHECK_EQ(inspect(none), "null pointer"); }
TEST("containers") { CHECK_EQ(inspect(std::vector<int>{ 1, 2, 3 }), "container of 3"); CHECK_EQ(inspect(std::string{ "hello" }), "container of 5"); }
TEST("everything else") { CHECK_EQ(inspect(Mystery{}), "unknown"); }

